# ------------------------------------------------------------------------- workspaces


@dataclass(frozen=True)
class StagedInput:
    name: str
    source_path: Path
    sha256: str


@dataclass
class Workspace:
    path: Path
    home: Path
    prompt_sha256: str
    schema_sha256: str
    input_sha256: str
    cli_schema_projection_sha256: str | None = None
    staged_sha256: dict[str, str] = field(default_factory=dict)
    baseline: dict[str, str] = field(default_factory=dict)

    def inventory(self) -> dict[str, str]:
        found: dict[str, str] = {}
        for item in sorted(self.path.rglob("*")):
            if item.is_file():
                found[str(item.relative_to(self.path))] = sha256_file(item)
        return found

    def assert_no_undeclared_writes(self, *, permitted_new: Sequence[str] = ()) -> None:
        after = self.inventory()
        allowed = set(permitted_new)
        for name, digest in after.items():
            if name in self.baseline:
                if self.baseline[name] != digest:
                    raise WorkspaceViolation(f"worker mutated staged file {name!r}")
            elif name not in allowed:
                raise WorkspaceViolation(f"worker wrote undeclared file {name!r}")

    def destroy(self) -> None:
        shutil.rmtree(self.path, ignore_errors=True)
        shutil.rmtree(self.home, ignore_errors=True)


def stage_workspace(
    *,
    output_root: Path | str,
    episode_id: str,
    activation_id: str,
    route: JobRoute,
    projection: Mapping[str, Any],
    authorization_receipt: Mapping[str, Any],
    staged_inputs: Sequence[StagedInput] = (),
    home_root: Path | str | None = None,
    cli_schema_projection: Mapping[str, Any] | None = None,
) -> Workspace:
    """Build the disposable activation directory described by spec 7.1."""
    root = Path(output_root).resolve() / ".workspaces" / episode_id / activation_id
    if root.exists():
        raise WorkspaceViolation(f"activation workspace already exists: {root}")
    root.mkdir(parents=True, mode=0o700)
    os.chmod(root, 0o700)

    home_parent = Path(home_root).resolve() if home_root else Path(tempfile.gettempdir()).resolve()
    home_parent.mkdir(parents=True, exist_ok=True)
    home = Path(tempfile.mkdtemp(prefix="plan26-home-", dir=str(home_parent)))
    os.chmod(home, 0o700)
    if route.cli == "claude":
        claude_auth_provision(home)
    elif route.cli == "codex":
        codex_auth_provision(home / "codex")

    prompt_source = resolve_prompt_path(route)
    schema_source = resolve_schema_path(route)
    schema = _load_json(schema_source)
    assert_no_authoritative_fields(schema, label=f"{route.job_id} output schema")

    payload = {"projection": dict(projection), "authorization_receipt": dict(authorization_receipt)}
    input_path = root / "authorized_input.json"
    input_path.write_text(canonical_json(payload), encoding="utf-8")
    shutil.copyfile(schema_source, root / "output.schema.json")
    shutil.copyfile(prompt_source, root / route.prompt)

    cli_schema_sha256: str | None = None
    if cli_schema_projection is not None:
        cli_schema_text = canonical_json(dict(cli_schema_projection))
        (root / "cli_schema_projection.json").write_text(cli_schema_text, encoding="utf-8")
        cli_schema_sha256 = sha256_bytes(cli_schema_text.encode("utf-8"))

    staged_digests: dict[str, str] = {}
    reserved = RESERVED_WORKSPACE_NAMES | {route.prompt}
    for item in staged_inputs:
        if not STAGED_NAME_PATTERN.match(item.name) or item.name in reserved:
            raise WorkspaceViolation(f"illegal staged input name: {item.name!r}")
        source = Path(item.source_path)
        if source.is_symlink() or not source.is_file():
            raise WorkspaceViolation(f"staged input is not a regular file: {source}")
        actual = sha256_file(source)
        if actual != item.sha256:
            raise WorkspaceViolation(
                f"staged input {item.name!r} hash {actual} != declared {item.sha256}")
        shutil.copyfile(source, root / item.name)
        os.chmod(root / item.name, stat.S_IRUSR)
        staged_digests[item.name] = actual

    workspace = Workspace(
        path=root,
        home=home,
        prompt_sha256=sha256_file(prompt_source),
        schema_sha256=sha256_file(schema_source),
        input_sha256=sha256_file(input_path),
        cli_schema_projection_sha256=cli_schema_sha256,
        staged_sha256=staged_digests,
    )
    workspace.baseline = workspace.inventory()
    return workspace

    records_dir = self.resolve(f"{stream.versions_dir}/records")
    if not records_dir.is_dir():
        return None
    versions = sorted(int(p.stem) for p in records_dir.glob("*.json"))
    if not versions:
        return None
    return self.read_version(stream, versions[-1])

def admit_version(
    self,
    stream: ArtifactStream,
    *,
    data: bytes,
    version: int,
    parent_hash: str | None,
    idempotency_key: str,
) -> VersionRecord:
    """Admit immutable artifact bytes as ``version`` of ``stream``."""
    if not isinstance(data, (bytes, bytearray)):
        raise ArtifactError("artifact data must be raw bytes")
    data = bytes(data)
    version = int(version)
    if version < 1:
        raise ArtifactError(f"version must be >= 1, got {version}")
    _require_token(idempotency_key, "idempotency_key")
    if parent_hash is not None:
        _require_hash(parent_hash, "parent_hash")

    content_hash = bytes_digest(data)
    body = {
        "schema": VERSION_RECORD_SCHEMA,
        "stream_id": stream.stream_id,
        "scope": stream.scope,
        "unit_id": stream.unit_id,
        "channel": stream.channel,
        "version": version,
        "parent_hash": parent_hash,
        "content_hash": content_hash,
        "byte_size": len(data),
        "artifact_path": stream.blob_path(content_hash),
        "idempotency_key": idempotency_key,
    }
    record = _record_from_body(body)

    key_relative = stream.key_path(idempotency_key)
    key_path = self.resolve(key_relative)
    if key_path.is_file():
        claimed = json.loads(key_path.read_text(encoding="utf-8"))
        existing = self.read_version(stream, claimed["version"])
        if existing is None:
            raise IntegrityError(f"idempotency key {idempotency_key!r} points at a missing version record")
        if existing.record_hash != record.record_hash:
            raise ArtifactConflict(
                f"idempotency key {idempotency_key!r} already admitted a different artifact "
                f"({existing.content_hash} != {content_hash})"
            )
        return existing

    existing_version = self.read_version(stream, version)
    if existing_version is not None:
        raise ArtifactConflict(
            f"version {version} of {stream.stream_id} already exists "
            f"({existing_version.content_hash})"
        )

    predecessor = self.read_version(stream, version - 1) if version > 1 else None
    if version == 1:
        if parent_hash is not None:
            raise ArtifactConflict("version 1 must declare parent_hash=None")
    else:
        if predecessor is None:
            raise ArtifactConflict(
                f"version {version} of {stream.stream_id} has no admitted parent version {version - 1}"
            )
        if parent_hash != predecessor.content_hash:
            raise ArtifactConflict(
                f"declared parent {parent_hash} does not match version {version - 1} "
                f"content hash {predecessor.content_hash}"
            )

    blob_relative = stream.blob_path(content_hash)
    blob_path = self.resolve(blob_relative)
    if blob_path.is_file():
        if file_digest(blob_path) != content_hash:
            raise IntegrityError(f"content-addressed blob is corrupt: {blob_relative}")
    else:
        self.put_bytes(blob_relative, data)

    self.put_bytes(
        stream.record_path(version),
        canonical_json_bytes({"record": body, "record_hash": record.record_hash}),
    )
    self.put_bytes(
        key_relative,
        canonical_json_bytes(
            {
                "idempotency_key": idempotency_key,
                "stream_id": stream.stream_id,
                "version": version,
                "content_hash": content_hash,
                "record_hash": record.record_hash,
            }
        ),
    )
    return record

def current_head(self, stream: ArtifactStream) -> VersionRecord | None:
    path = self.resolve(stream.head_path)
    if not path.is_file():
        return None
    stored = json.loads(path.read_text(encoding="utf-8"))
    record = _record_from_body(stored["record"])
    if record.record_hash != stored["record_hash"]:
        raise IntegrityError(f"head record hash mismatch at {stream.head_path}")
    return record

def advance_head(self, stream: ArtifactStream, record: VersionRecord) -> VersionRecord:
    """Advance the head pointer to a child of the current head only."""
    if record.stream_id != stream.stream_id:
        raise HeadAdvanceError(
            f"record belongs to {record.stream_id}, not {stream.stream_id}"
        )
    admitted = self.read_version(stream, record.version)
    if admitted is None or admitted.record_hash != record.record_hash:
        raise HeadAdvanceError(
            f"version {record.version} of {stream.stream_id} is not an admitted artifact"
        )
    current = self.current_head(stream)
    if current is None:
        if record.version != 1 or record.parent_hash is not None:
            raise HeadAdvanceError(
                "first head must be version 1 with parent_hash=None, "
                f"got version {record.version} parent {record.parent_hash}"
            )
    else:
        if record.version != current.version + 1:
            raise HeadAdvanceError(
                f"head advances one version at a time: current {current.version}, "
                f"proposed {record.version}"
            )
        if record.parent_hash != current.content_hash:
            raise HeadAdvanceError(
                f"declared parent {record.parent_hash} is not the current head "
                f"{current.content_hash}"
            )
    self.put_bytes(
        stream.head_path,
        canonical_json_bytes({"record": record.body(), "record_hash": record.record_hash}),
        overwrite=True,
    )
    return record

def accept(
    self,
    stream: ArtifactStream,
    *,
    receipt_hash: str,
    files: Mapping[str, bytes],
) -> dict[str, str]:
    """Copy bytes into a write-protected ``accepted/<receipt_hash>/`` directory."""
    _require_hash(receipt_hash, "receipt_hash")
    if not files:
        raise ArtifactError("accept requires at least one file")
    payload = {}
    for name, data in files.items():
        if not isinstance(data, (bytes, bytearray)):
            raise ArtifactError(f"accepted file {name!r} must be raw bytes")
        payload[name] = bytes(data)

    accepted_relative = stream.accepted_dir(receipt_hash)
    accepted_dir = self.resolve(accepted_relative)
    targets = {
        name: self.resolve(f"{accepted_relative}/{name}") for name in payload
    }

    if accepted_dir.exists():
        present = {
            str(p.relative_to(accepted_dir).as_posix())
            for p in accepted_dir.rglob("*")
            if p.is_file()
        }
        if present != set(payload):
            raise AcceptedImmutable(
                f"accepted receipt {receipt_hash} already exists with a different file set"
            )
        for name, data in payload.items():
            if file_digest(targets[name]) != bytes_digest(data):
                raise AcceptedImmutable(
                    f"accepted receipt {receipt_hash} already exists with different bytes for {name!r}"
                )
        return {name: bytes_digest(data) for name, data in payload.items()}

    staged = {name: self.stage(data) for name, data in payload.items()}
    try:
        for name, source in staged.items():
            target = targets[name]
            target.parent.mkdir(parents=True, exist_ok=True)
            os.replace(source, target)
            self._fsync_dir(target.parent)
    except BaseException:
        for source in staged.values():
            Path(source).unlink(missing_ok=True)
        raise

    for target in targets.values():
        os.chmod(target, _ACCEPTED_FILE_MODE)
    for directory in sorted(
        {p for p in accepted_dir.rglob("*") if p.is_dir()} | {accepted_dir},
        key=lambda p: len(p.parts),
        reverse=True,
    ):
        os.chmod(directory, _ACCEPTED_DIR_MODE)
    return {name: bytes_digest(data) for name, data in payload.items()}

def verify_artifact(self, record: VersionRecord) -> bool:
    """Recompute the digest from the bytes on disk; never trusts a claim."""
    path = self.resolve(record.artifact_path)
    if not path.is_file():
        return False
    return file_digest(path) == record.content_hash and path.stat().st_size == record.byte_size

def is_write_protected(self, relative: str) -> bool:
    path = self.resolve(relative)
    if not path.exists():
        return False
    return not bool(stat.S_IMODE(path.stat().st_mode) & (stat.S_IWUSR | stat.S_IWGRP | stat.S_IWOTH))

#!/usr/bin/env python3
"""Run 27 implementation-graph controller.

Mutating commands:  begin, admit, readmit, resume, recover
Read-only commands: status, plan, validate, audit, verify-live-proof,
                    verify-final-audit

Read-only commands never create the state directory, never write a receipt, and
never touch an attempt.
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Any

_HERE = Path(__file__).resolve().parent
if str(_HERE) not in sys.path:
    sys.path.insert(0, str(_HERE))

from core import (  # noqa: E402
    ADMISSIBLE_OUTCOMES,
    DEFAULT_GRAPH_PATH,
    DEFAULT_REPO_ROOT,
    DEFAULT_STATE_DIR,
    ControllerError,
    Graph,
    load_node_result,
    sha256_file,
)
from scheduler import RECOVERY_REASON_CODES, Scheduler  # noqa: E402


DEFAULT_LIVE_PROOF_CLI = "runtime/run_curriculum.py"
DEFAULT_FORBIDDEN_LIVE_MARKERS = (
    "SIMULATED",
    "FAKE_TRANSPORT",
    "MOCK_TRANSPORT",
    "STUB_TRANSPORT",
    "SYNTHETIC_CURRICULUM",
)

READ_ONLY_COMMANDS = frozenset(
    {"status", "plan", "validate", "audit", "verify-live-proof", "verify-final-audit"}
)


def build_scheduler(arguments: argparse.Namespace) -> Scheduler:
    graph = Graph.load(arguments.graph, arguments.repo_root)
    return Scheduler(graph, arguments.state_dir, run_id=arguments.run_id)


# --------------------------------------------------------------- live proof


def verify_live_proof(scheduler: Scheduler, node_id: str) -> dict[str, Any]:
    graph = scheduler.graph
    node = graph.node(node_id)
    problems: list[dict[str, str]] = []

    def fail(code: str, message: str) -> None:
        problems.append({"code": code, "message": message})

    if node_id not in graph.live_proof_nodes():
        raise ControllerError(
            f"{node_id} is not a live-proof node; the graph does not allow it to "
            "report NOT_AVAILABLE",
            code="NOT_A_LIVE_PROOF_NODE",
        )

    result = load_node_result(graph, node_id)
    outcome = result["outcome"]
    cli = graph.rules.get("live_proof_cli", DEFAULT_LIVE_PROOF_CLI)
    markers = tuple(graph.rules.get("live_proof_forbidden_markers", DEFAULT_FORBIDDEN_LIVE_MARKERS))

    log_paths = [command["log"] for command in result["commands"]]
    scanned = sorted({*log_paths, *result["evidence"]})

    if outcome == "PASSED":
        for command in result["commands"]:
            if command["exit_code"] != 0:
                fail("NONZERO_LIVE_COMMAND", f"{command['argv']} exited {command['exit_code']}")
        if not any(cli in " ".join(command["argv"]) for command in result["commands"]):
            fail(
                "NO_PRODUCTION_CLI_INVOCATION",
                f"a passing live proof must invoke the production CLI {cli}",
            )
        for relative in node["writes"]:
            target = graph.repo_root / relative
            if not target.exists():
                fail("LIVE_OUTPUT_MISSING", f"declared live output is missing: {relative}")
            elif target.is_dir() and not any(
                item.is_file() for item in target.rglob("*")
            ):
                fail("LIVE_OUTPUT_EMPTY", f"declared live output directory is empty: {relative}")
        for item in result["changed_files"]:
            target = graph.repo_root / item["path"]
            if item["change"] != "deleted":
                if not target.is_file():
                    fail("CHANGED_FILE_MISSING", f"missing changed file: {item['path']}")
                elif sha256_file(target) != item["sha256"]:
                    fail("CHANGED_FILE_DIGEST_MISMATCH", f"digest mismatch: {item['path']}")
        for relative in scanned:
            target = graph.repo_root / relative
            if not target.is_file():
                continue
            text = target.read_text(encoding="utf-8", errors="replace")
            for marker in markers:
                if marker in text:
                    fail(
                        "SIMULATED_LIVE_EVIDENCE",
                        f"{relative} contains the non-live marker {marker}",
                    )
    elif outcome == "NOT_AVAILABLE":
        if not any(finding["disposition"] == "open" for finding in result["findings"]):
            fail(
                "UNEXPLAINED_NOT_AVAILABLE",
                "NOT_AVAILABLE must carry at least one open finding naming why live "
                "proof could not be produced",
            )
    else:
        fail("OUTCOME_NOT_LIVE_PROOF", f"outcome {outcome!r} does not report live proof")

    for relative in result["evidence"]:
        if not (graph.repo_root / relative).exists():
            fail("EVIDENCE_MISSING", f"evidence path is missing: {relative}")

    for ancestor in graph.ancestors(node_id):
        if scheduler.receipt(ancestor) is None:
            continue
        state = scheduler.currency(ancestor)
        if not state["current"]:
            fail("ANCESTOR_NOT_CURRENT", f"{ancestor}: {state['reasons']}")

    return {
        "command": "verify-live-proof",
        "node_id": node_id,
        "outcome": outcome,
        "valid": not problems,
        "problems": problems,
    }


# -------------------------------------------------------------- final audit


def verify_final_audit(scheduler: Scheduler, node_id: str) -> dict[str, Any]:
    graph = scheduler.graph
    problems: list[dict[str, str]] = []

    def fail(code: str, message: str) -> None:
        problems.append({"code": code, "message": message})

    expected = graph.final_audit_node()
    if node_id != expected:
        raise ControllerError(
            f"{node_id} is not the final audit node; the graph's single sink is {expected}",
            code="NOT_THE_FINAL_AUDIT_NODE",
        )

    result = load_node_result(graph, node_id)
    terminal = result.get("terminal_recommendation")
    legal = set(graph.data["terminals"])
    if terminal is None:
        fail("NO_TERMINAL_RECOMMENDATION", "the final audit must recommend exactly one terminal")
    elif terminal not in legal:
        fail("ILLEGAL_TERMINAL", f"{terminal!r} is not one of {sorted(legal)}")

    outcomes: dict[str, str] = {}
    for other in graph.order():
        if other == node_id:
            continue
        try:
            other_result = load_node_result(graph, other)
        except ControllerError as error:
            fail("UPSTREAM_RESULT_UNUSABLE", f"{other}: {error}")
            continue
        outcomes[other] = other_result["outcome"]
        if other_result["outcome"] not in ADMISSIBLE_OUTCOMES:
            fail("UPSTREAM_NOT_ADMISSIBLE", f"{other} reported {other_result['outcome']}")
        if other_result.get("terminal_recommendation") is not None:
            fail("NON_AUDIT_TERMINAL", f"{other} may not recommend a terminal")

    live_nodes = [item for item in graph.live_proof_nodes() if item != node_id]
    if terminal == "ACTIVATED":
        for live in live_nodes:
            if outcomes.get(live) != "PASSED":
                fail(
                    "ACTIVATION_WITHOUT_LIVE_PROOF",
                    f"{live} reported {outcomes.get(live)!r}; ACTIVATED requires live proof",
                )
    elif terminal == "REMEDIATION_VERIFIED_NOT_ACTIVATED":
        if not any(outcomes.get(live) == "NOT_AVAILABLE" for live in live_nodes):
            fail(
                "NOT_ACTIVATED_WITHOUT_UNAVAILABLE_PROOF",
                "this terminal requires at least one live-proof node reporting NOT_AVAILABLE",
            )
    elif terminal == "BLOCKED" and result["outcome"] != "BLOCKED":
        fail("BLOCKED_TERMINAL_MISMATCH", "a BLOCKED terminal requires a BLOCKED outcome")

    for other in graph.order():
        if scheduler.receipt(other) is None:
            continue
        state = scheduler.currency(other)
        if not state["current"]:
            fail(
                "INVALIDATED_RECEIPT_FEEDS_FINAL_AUDIT",
                f"{other} is not current: {state['reasons']}",
            )

    for relative in result["evidence"]:
        if not (graph.repo_root / relative).exists():
            fail("EVIDENCE_MISSING", f"evidence path is missing: {relative}")

    return {
        "command": "verify-final-audit",
        "node_id": node_id,
        "outcome": result["outcome"],
        "terminal_recommendation": terminal,
        "upstream_outcomes": outcomes,
        "valid": not problems,
        "problems": problems,
    }


# ---------------------------------------------------------------------- CLI


def parser() -> argparse.ArgumentParser:
    result = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    result.add_argument("--graph", type=Path, default=DEFAULT_GRAPH_PATH)
